  let data = try Data(contentsOf: url)
  let jsonData = try JSONSerialization.jsonObject(with: data, options: .allowFragments) as? [String: Any]
  if let attractions = jsonData?["attractions"] as? [[String: Any]] {
    let sortedAttractions = attractions.sorted { ($0["rating"] as? Double ?? 0.0) > ($1["rating"] as? Double ?? 0.0) }
    print("Top Three Tourist Destinations in Hawaii:")
    for i in 0..<min(sortedAttractions.count, 3) {
      let attraction = sortedAttractions[i]
      let name = attraction["name"] as? String ?? ""
      let description = attraction["description"] as? String ?? ""
      let location = attraction["location"] as? String ?? ""
      let rating = attraction["rating"] as? Double ?? 0.0

      print("\n\(i+1). \(name) (\(location)): \(description) - Rating: \(rating)")

      if let hotels = jsonData?["hotels"] as? [[String: Any]] {
        let cheapestHotel = hotels.filter { ($0["location"] as? String ?? "") == location }
                                   .sorted { ($0["price_per_night"] as? String ?? "") < ($1["price_per_night"] as? String ?? "") }
                                   .first
        if let hotel = cheapestHotel {
          let hotelName = hotel["name"] as? String ?? ""
          let hotelPrice = hotel["price_per_night"] as? String ?? ""
          print("- Cheapest hotel option: \(hotelName) (\(location)) - Price per night: \(hotelPrice)")
        }
      }

      if let transportation = jsonData?["transportation"] as? [[String: Any]] {
        let cheapestTransportation = transportation.filter { ($0["location"] as? String ?? "") == location }
                                                   .sorted {
                                                     if let price1 = $0["price_per_day"] as? String, let price2 = $1["price_per_day"] as? String {
                                                       return price1 < price2
                                                     } else if let price1 = $0["price_per_person"] as? String, let price2 = $1["price_per_person"] as? String {
                                                       return price1 < price2
                                                     } else {
                                                       return true
                                                     }
                                                   }
                                                   .first
        if let transport = cheapestTransportation {
          let transportType = transport["type"] as? String ?? ""
          let transportCompany = transport["company"] as? String ?? ""
          if let price = transport["price_per_day"] as? String {
            print("- Cheapest transportation option: \(transportCompany) \(transportType) (\(location)) - Price per day: \(price)")
          } else if let price = transport["price_per_person"] as? String {
            print("- Cheapest transportation option: \(transportCompany) \(transportType) (\(location)) - Price per person: \(price)")
          }
        }
      }
    }
  }
} catch {
  print("Error reading JSON file: \(error)")
}

