func encryptMessage(message: String, key: Int) -> String {
    var encryptedMessage = ""
    for char in message.unicodeScalars {
        let encryptedChar = Character(UnicodeScalar(Int(char.value) + key)!)
        encryptedMessage.append(encryptedChar)
    }
    return encryptedMessage
}
// This function takes in a message and a unique key for each transaction, and returns the encrypted message using the key to shift the unicode scalar values of each character in the message.
