```swift
func encryptMessage(message: String) -> (encryptedMessage: String, key: Int) {
    let key = Int.random(in: 1...100) // Generate a random key between 1 and 100
    var encryptedMessage = ""
    for char in message.unicodeScalars {
        let encryptedChar = Character(UnicodeScalar(Int(char.value) * key)!)
        encryptedMessage.append(encryptedChar)
    }
    return (encryptedMessage, key)
}
func decryptMessage(encryptedMessage: String, key: Int) -> String {
    var decryptedMessage = ""
    for char in encryptedMessage.unicodeScalars {
        let decryptedChar = Character(UnicodeScalar(Int(char.value) / key)!)
        decryptedMessage.append(decryptedChar)
    }
    return decryptedMessage
}
```
This new encryption method generates a random key between 1 and 100, and multiplies each character's Unicode scalar value by the key to encrypt the message. To decrypt the message, we divide each character's Unicode scalar value by the key.
