savings = 10000;
total_savings = savings * (65 - 25);
expenses = 50000;
years_covered = 85 - 65;
total_expenses = expenses * years_covered;
inflation_adjusted_expenses = total_expenses / (1 + 0.02)^years_covered;
investment_return = total_savings * (1 + 0.06)^years_covered;
inflation_adjusted_return = investment_return / (1 + 0.02)^years_covered;
total_income = inflation_adjusted_expenses + inflation_adjusted_return;
% No retirement savings scenario
expenses = 50000;
years_covered = 85 - 65;
total_expenses = expenses * years_covered;
inflation_adjusted_expenses = total_expenses / (1 + 0.02)^years_covered;
total_income = inflation_adjusted_expenses;
```
