func findSecondHighestNumber(in array: [Int]) -> Int {
    var highest = Int.min
    var secondHighest = Int.min

    for number in array {
        if number > highest {
            secondHighest = highest
            highest = number
        } else if number > secondHighest && number != highest {
            secondHighest = number
        }
    }

    return secondHighest
}
