public static double estimateCropYield(double temperature, double precipitation, double corr) {
   // use linear regression to estimate crop yield
   double slope = corr * (standardDeviation(cropYield) / standardDeviation(temperature));
   double intercept = mean(cropYield) - slope * mean(temperature);
   return slope * temperature + intercept;
