public static double mean(double[] data) {
   double sum = 0;
   for (double d : data) {
      sum += d;
   }
   return sum / data.length;
}
public static double standardDeviation(double[] data) {
   double mean = mean(data);
   double sum = 0;
   for (double d : data) {
      sum += (d - mean) * (d - mean);
   }
   return Math.sqrt(sum / (data.length - 1));
