```
using System;
using System.Collections.Generic;
using System.Linq;
class NaiveBayesClassifier
{
    private Dictionary<string, double> _classProbabilities;
    private Dictionary<string, Dictionary<string, double>> _wordProbabilities;
    public NaiveBayesClassifier(List<string> trainingData)
    {
        _classProbabilities = new Dictionary<string, double>();
        _wordProbabilities = new Dictionary<string, Dictionary<string, double>>();
        // Calculate class probabilities
        var classCounts = new Dictionary<string, int>();
        foreach (var data in trainingData)
        {
            var parts = data.Split(',');
            var className = parts[parts.Length - 1];
            if (!classCounts.ContainsKey(className))
            {
                classCounts[className] = 0;
            }
            classCounts[className]++;
        }
        var totalCount = classCounts.Values.Sum();
        foreach (var className in classCounts.Keys)
        {
            _classProbabilities[className] = (double)classCounts[className] / totalCount;
        }
        // Calculate word probabilities
        var wordCounts = new Dictionary<string, Dictionary<string, int>>();
        foreach (var data in trainingData)
        {
            var parts = data.Split(',');
            var className = parts[parts.Length - 1];
            for (int i = 0; i < parts.Length - 1; i++)
            {
                var word = parts[i];
                if (!wordCounts.ContainsKey(className))
                {
                    wordCounts[className] = new Dictionary<string, int>();
                }
                if (!wordCounts[className].ContainsKey(word))
                {
                    wordCounts[className][word] = 0;
                }
                wordCounts[className][word]++;
            }
        }
        foreach (var className in wordCounts.Keys)
        {
            _wordProbabilities[className] = new Dictionary<string, double>();
            var totalWords = wordCounts[className].Values.Sum();
            foreach (var word in wordCounts[className].Keys)
            {
                _wordProbabilities[className][word] = (double)wordCounts[className][word] / totalWords;
            }
        }
    }
    public string Classify(string input)
    {
        var parts = input.Split(',');
        var wordProbabilities = new Dictionary<string, double>();
        foreach (var className in _classProbabilities.Keys)
        {
            wordProbabilities[className] = 1;
            for (int i = 0; i < parts.Length - 1; i++)
            {
                var word = parts[i];
                if (_wordProbabilities[className].ContainsKey(word))
                {
                    wordProbabilities[className] *= _wordProbabilities[className][word];
                }
            }
            wordProbabilities[className] *= _classProbabilities[className];
        }
        return wordProbabilities.OrderByDescending(x => x.Value).First().Key;
    }
}
