package main
import (
    "fmt"
    "math"
    "math/cmplx"
)
func nthRootOfComplexNumber(z complex128, n int) complex128 {
    // convert the complex number into polar form
    r := cmplx.Abs(z)
    theta := cmplx.Phase(z)
    // compute the nth root of the magnitude
    nthRootOfMagnitude := cmplx.Pow(r, 1/float64(n))
    // compute the nth roots of unity
    nthRootsOfUnity := make([]complex128, n)
    for k := 0; k < n; k++ {
        thetaK := theta + 2*math.Pi*float64(k)/float64(n)
        nthRootsOfUnity[k] = cmplx.Rect(nthRootOfMagnitude, thetaK)
    }
    // return the nth root closest to the real axis
    minDistanceFromRealAxis := math.Inf(1)
    var nthRoot complex128
    for _, root := range nthRootsOfUnity {
        distanceFromRealAxis := cmplx.Abs(complex(real(root), 0))
        if distanceFromRealAxis < minDistanceFromRealAxis {
            minDistanceFromRealAxis = distanceFromRealAxis
            nthRoot = root
        }
    }
    return nthRoot
}
