```
// Define the graph as an adjacency matrix
const graph = [
  [0, 5, 10, 0, 0],
  [5, 0, 3, 8, 0],
  [10, 3, 0, 1, 2],
  [0, 8, 1, 0, 4],
  [0, 0, 2, 4, 0],
];
// Define the passenger demand and bus capacity
const passengerDemand = [20, 30, 10, 25, 15];
const busCapacity = 50;
// Define the battery charge levels and fuel efficiency
const batteryChargeLevels = [100, 90, 80, 70, 60];
const fuelEfficiency = [10, 8, 6, 4, 2];
// Define the optimization algorithm (Dijkstra's algorithm)
function dijkstra(graph, startNode, endNode) {
  const distances = {};
  const visited = {};
  const previous = {};
  for (let i = 0; i < graph.length; i++) {
    distances[i] = Infinity;
  }
  distances[startNode] = 0;
  while (!visited[endNode]) {
    let currentNode = null;
    let shortestDistance = Infinity;
    for (let i = 0; i < graph.length; i++) {
      if (!visited[i] && distances[i] < shortestDistance) {
        currentNode = i;
        shortestDistance = distances[i];
      }
    }
    for (let i = 0; i < graph[currentNode].length; i++) {
      const weight = graph[currentNode][i];
      if (weight > 0) {
        const distance = distances[currentNode] + weight;
        if (distance < distances[i]) {
          distances[i] = distance;
          previous[i] = currentNode;
        }
      }
    }
    visited[currentNode] = true;
  }
  const path = [];
  let currentNode = endNode;
  while (currentNode !== startNode) {
    path.unshift(currentNode);
    currentNode = previous[currentNode];
  }
  path.unshift(startNode);
  return path;
}
// Define the function to optimize the bus routes
function optimizeRoutes(graph, passengerDemand, busCapacity, batteryChargeLevels, fuelEfficiency) {
  const routes = [];
  for (let i = 0; i < passengerDemand.length; i++) {
    const startNode = i;
    const endNode = passengerDemand.indexOf(Math.max(...passengerDemand));
    const path = dijkstra(graph, startNode, endNode);
    let currentCapacity = 0;
    let currentChargeLevel = batteryChargeLevels[startNode];
    let distanceTraveled = 0;
    const route = [startNode];
    for (let j = 0; j < path.length - 1; j++) {
      const currentNode = path[j];
      const nextNode = path[j + 1];
      const weight = graph[currentNode][nextNode];
      currentCapacity += passengerDemand[currentNode];
      currentChargeLevel -= weight / fuelEfficiency[currentNode];
      distanceTraveled += weight;
      if (currentCapacity > busCapacity || currentChargeLevel < 0) {
        route.push(currentNode);
        routes.push(route);
        route = [currentNode];
        currentCapacity = passengerDemand[currentNode];
        currentChargeLevel = batteryChargeLevels[startNode];
        distanceTraveled = 0;
      }
    }
    route.push(endNode);
    routes.push(route);
    passengerDemand[startNode] = 0;
  }
  return routes;
}
// Call the function to optimize the bus routes
const routes = optimizeRoutes(graph, passengerDemand, busCapacity, batteryChargeLevels, fuelEfficiency);
console.log(routes);
