```
#include <iostream>
#include <algorithm>
using namespace std;
int magicBox(int arr[], int subseq[], int n, int m) {
    sort(arr, arr+n, greater<int>());
    sort(subseq, subseq+m, greater<int>());
    for(int i=0; i<=n-m; i++) {
        bool found = true;
        for(int j=0; j<m; j++) {
            if(arr[i+j] != subseq[j]) {
                found = false;
                break;
            }
        }
        if(found) {
            return i;
        }
    }
    return -1;
}
int main() {
    int arr[] = {9, 5, 3, 7, 6};
    int subseq[] = {7, 5};
    int n = sizeof(arr)/sizeof(arr[0]);
    int m = sizeof(subseq)/sizeof(subseq[0]);
    int index = magicBox(arr, subseq, n, m);
    if(index == -1) {
        cout << "Subsequence not found" << endl;
    } else {
        cout << "Subsequence found at index " << index << endl;
    }
    return 0;
}
```
